import { MeshStandardNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, time, uniform, Fn, abs, fract, dot } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const Group = THREE.Group;
  const Color = THREE.Color;
  const Vector2 = THREE.Vector2;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };
  const inkColor = new Color(colors.ink);
  const accentColor = new Color(colors.accent);
  const surfaceColor = new Color(colors.surface);
  const paperColor = new Color(colors.paper);

  const group = new Group();
  group.name = 'features-row';

  // Backdrop plane carrying the spec surface gradient (dark-first, never flat void)
  const stageGeo = new THREE.PlaneGeometry(7, 6);
  const stageMat = new THREE.MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  stageMat.colorNode = mix(
    vec3(0.035, 0.035, 0.050),
    vec3(surfaceColor.r * 0.45, surfaceColor.g * 0.45, surfaceColor.b * 0.45),
    smoothstep(0.0, 1.0, uv().y)
  );
  const stage = new THREE.Mesh(stageGeo, stageMat);
  stage.position.set(0, 0, -2.5);
  stage.renderOrder = -10;
  group.add(stage);

  // Subject: horizontal row card (4 wide x 1 tall) extruded PBR card backs
  const W = 4;
  const H = 1;
  const cardGeo = new THREE.PlaneGeometry(W, H, 64, 64);

  // Uniforms
  const focusUniform = uniform(0);
  const hoverUniform = uniform(0);
  const pointerUniform = uniform(new Vector2(0, 0));
  const depthTexUniform = uniform(null);
  const imageTexUniform = uniform(null);

  const mat = new MeshStandardNodeMaterial({ transparent: false });
  mat.roughness = 0.55;
  mat.metalness = 0.45;
  mat.emissiveIntensity = 1.0;

  // Base albedo: ink surface with subtle vertical grade
  const baseAlbedo = Fn(() => {
    const g = mix(
      vec3(inkColor.r * 0.6, inkColor.g * 0.6, inkColor.b * 0.6),
      vec3(inkColor.r * 0.95, inkColor.g * 0.95, inkColor.b * 0.95),
      uv().y
    );
    return g;
  })();

  // Image texture overlays once loaded; tilt to surface until then
  const imageAlbedo = Fn(() => {
    const tex = imageTexUniform;
    const has = tex.notEqual(null);
    const sampled = tex.context(uv(), 0.0).rgb;
    return mix(baseAlbedo, sampled, has);
  });

  mat.colorNode = Fn(() => {
    const base = imageAlbedo();
    // Accent edge tint on focus
    const edge = smoothstep(0.46, 0.50, abs(uv().x.sub(0.5)));
    const accentTint = vec3(accentColor).mul(edge).mul(focusUniform);
    return base.add(accentTint.mul(0.6));
  })();

  // Subtle time-driven parallax breathing + pointer offset (cursor parallax)
  const localUv = uv().sub(0.5);
  const pointerOffset = pointerUniform.sub(0.5).mul(0.12);
  const parallax = localUv.add(pointerOffset);

  // Displacement via depth map (subtle, <0.06 scene units)
  mat.positionNode = Fn(() => {
    const dTex = depthTexUniform;
    const hasD = dTex.notEqual(null);
    const sampled = dTex.context(parallax, 0.0).r;
    const depth = mix(float(0.5), sampled, hasD);
    const breath = time.mul(0.25).sin().mul(0.005);
    const dispZ = depth.mul(0.08).add(breath).mul(hoverUniform.add(0.25));
    return vec3(0.0, 0.0, dispZ);
  })();

  mat.emissiveNode = Fn(() => {
    const accent = vec3(accentColor);
    const edge = smoothstep(0.46, 0.50, abs(uv().x.sub(0.5)));
    return accent.mul(edge).mul(focusUniform.mul(0.7));
  })();

  const card = new THREE.Mesh(cardGeo, mat);
  card.position.set(0, 0, 0);
  group.add(card);

  // Rim + key lights node-local (intensity <=1.5)
  const rim = new THREE.PointLight(accentColor, 0.8, 8, 1.5);
  rim.position.set(-2.2, 1.0, 1.4);
  group.add(rim);

  const key = new THREE.DirectionalLight(0xffffff, 1.0);
  key.position.set(2.5, 2.0, 4);
  group.add(key);

  const fill = new THREE.DirectionalLight(paperColor, 0.35);
  fill.position.set(-3, -2, 2);
  group.add(fill);

  // Card text overlay (spec lists no text content for THIS row node -
  // sibling nodes carry title/label; row shows accent divider line only).
  // Accent divider: thin extruded bar within the card frame
  const dividerGeo = new THREE.BoxGeometry(3.6, 0.02, 0.04);
  const dividerMat = new THREE.MeshStandardNodeMaterial({ transparent: false });
  dividerMat.colorNode = vec3(accentColor).mul(0.85);
  dividerMat.emissiveNode = vec3(accentColor).mul(0.45);
  dividerMat.metalness = 0.4;
  dividerMat.roughness = 0.45;
  const divider = new THREE.Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -0.42, 0.02);
  group.add(divider);

  // Top hairline (paper-colored) for engineered card edge
  const topLineGeo = new THREE.BoxGeometry(3.6, 0.01, 0.02);
  const topLineMat = new THREE.MeshStandardNodeMaterial({ transparent: true });
  topLineMat.colorNode = vec3(paperColor).mul(0.22);
  topLineMat.metalness = 0.55;
  topLineMat.roughness = 0.5;
  const topLine = new THREE.Mesh(topLineGeo, topLineMat);
  topLine.position.set(0, 0.46, 0.02);
  group.add(topLine);

  // Contact shadow plane below the card
  const shadowGeo = new THREE.PlaneGeometry(W * 1.4, H * 1.6);
  const shadowMat = new THREE.MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.alphaNode = (() => {
    const d = uv().sub(0.5);
    const r = dot(d, d).sqrt();
    return smoothstep(0.5, 0.0, r).mul(0.5);
  })();
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -0.55, -0.15);
  shadow.rotation.x = -Math.PI / 12;
  group.add(shadow);

  // Entrance timeline
  const tl = gsap.timeline();
  tl.from(card.position, { y: 0.4, duration: 0.7, ease: 'power3.out' })
    .from(card.material, { opacity: 0, duration: 0.5, ease: 'power2.out' }, 0)
    .from(divider.position, { x: -0.3, duration: 0.6, ease: 'power3.out' }, 0.1)
    .from(topLine.position, { x: 0.3, duration: 0.6, ease: 'power3.out' }, 0.1)
    .to(hoverUniform, { value: 0.0, duration: 0 }, 0);

  const primitivesToKeep = [];
  // No cinematic primitives listed; parallax handled inline via TSL.

  // Load textures
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.minFilter = THREE.LinearMipmapLinearFilter;
      tex.magFilter = THREE.LinearFilter;
      imageTexUniform.value = tex;
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTexUniform.value = tex;
    });
  }

  // Event handlers attached to userData.handlers.*
  const pressTween = { current: null };
  const hoverTween = { current: null };

  function setHover(v) {
    if (hoverTween.current) hoverTween.current.kill();
    hoverTween.current = gsap.to(hoverUniform, { value: v, duration: 0.45, ease: 'power2.out' });
    hoverTween.current = gsap.to(card.position, {
      y: v > 0 ? 0.15 : 0,
      duration: v > 0 ? 0.6 : 0.9,
      ease: v > 0 ? 'power3.out' : 'power4.out',
      overwrite: true,
    });
    focusTween.current = gsap.to(focusUniform, { value: v ? 0.6 : 0, duration: 0.3, ease: 'power2.out' });
  }
  const focusTween = { current: null };

  group.userData.handlers = {
    onPointerMove: (e) => {
      pointerUniform.value.set(e.uv?.x ?? 0.5, e.uv?.y ?? 0.5);
    },
    onHover: () => setHover(1),
    onHoverEnd: () => setHover(0),
    onFocus: () => {
      if (focusTween.current) focusTween.current.kill();
      focusTween.current = gsap.to(focusUniform, { value: 0.8, duration: 0.3, ease: 'power2.out' });
    },
    onBlur: () => {
      if (focusTween.current) focusTween.current.kill();
      focusTween.current = gsap.to(focusUniform, { value: 0, duration: 0.4, ease: 'power2.inOut' });
    },
    onClick: (e) => {
      if (pressTween.current) pressTween.current.kill();
      pressTween.current = gsap.timeline()
        .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
        .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.4, ease: 'power4.out' });
      ctx.emit('navigate', { to: 'hub-features' });
      ctx.emit('hub-features.select', { id: config.id });
    },
    onKeyDown: (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        ctx.emit('navigate', { to: 'hub-features' });
      }
    },
  };

  group.userData.cleanup = () => {
    if (hoverTween.current) hoverTween.current.kill();
    if (pressTween.current) pressTween.current.kill();
    if (focusTween.current) focusTween.current.kill();
    tl.kill();
    cardGeo.dispose();
    stageGeo.dispose();
    shadowGeo.dispose();
    dividerGeo.dispose();
    topLineGeo.dispose();
    mat.dispose();
    stageMat.dispose();
    shadowMat.dispose();
    dividerMat.dispose();
    topLineMat.dispose();
    if (imageTexUniform.value) imageTexUniform.value.dispose?.();
    if (depthTexUniform.value) depthTexUniform.value.dispose?.();
    for (const p of primitivesToKeep) p.cleanup?.();
  };

  return group;
}
